]$arsenal$::jsonb) as source(item)
on conflict (slug) do update set data = existing.data || jsonb_build_object(
  'cardNumber', excluded.data->'cardNumber',
  'icon', coalesce(existing.data->'icon', excluded.data->'icon'),
  'image', coalesce(existing.data->'image', excluded.data->'image')
)
where existing.data->'cardNumber' is distinct from excluded.data->'cardNumber'
   or existing.data->'icon' is null
   or existing.data->'image' is null;
